<script setup lang="ts">import {computed,ref} from 'vue';export type Notice={id:string;title:string;message?:string;read?:boolean;time?:string};const p=defineProps<{items:Notice[]}>();const emit=defineEmits<{read:[id:string];clear:[]}>();const unreadOnly=ref(false);const visible=computed(()=>p.items.filter(n=>!unreadOnly.value||!n.read))</script><template><section class="vx-notification-centre"><header><h3>Notifications</h3><label><input v-model="unreadOnly" type="checkbox"/> Unread only</label><button type="button" @click="emit('clear')">Clear</button></header><div v-for="notice in visible" :key="notice.id" class="vx-notification-centre__item" :class="{'is-unread':!notice.read}"><strong>{{notice.title}}</strong><small v-if="notice.time">{{notice.time}}</small><p>{{notice.message}}</p><button v-if="!notice.read" type="button" @click="emit('read',notice.id)">Mark read</button></div><p v-if="!visible.length">No notifications</p></section></template>
